CREATE SEQUENCE graphile_worker.claim_retries; CREATE SEQUENCE graphile_worker.outcome_retries; CREATE FUNCTION graphile_worker.transient_claim() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF nextval('graphile_worker.claim_retries') <= 2 THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='transient claim'; END IF; RETURN NEW; END $$; CREATE TRIGGER transient_claim BEFORE UPDATE ON graphile_worker._private_jobs FOR EACH ROW WHEN (OLD.locked_by IS NULL AND NEW.locked_by IS NOT NULL) EXECUTE FUNCTION graphile_worker.transient_claim(); CREATE FUNCTION graphile_worker.transient_outcome() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF nextval('graphile_worker.outcome_retries') <= 2 THEN RAISE EXCEPTION USING ERRCODE='40P01', MESSAGE='transient outcome'; END IF; IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END $$;
